# Ш100–Ш102: «Атака на босса», the wall then the hero — new keys → keys.json + src/tr19.txt
import json, re
KJ = 'tools/i18n/keys.json'
keys = json.load(open(KJ, encoding='utf8'))
LET = 'A-Za-zА-Яа-яЁёІіЇїЄєÀ-ÿ'
CORE = re.compile(rf'^([^{LET}{{}}\d]*)([\s\S]*?)([^{LET}{{}}\d]*)$')
def key(t):
    b = re.sub(r'\s+', ' ', CORE.match(t).group(2)).strip()
    return re.sub(r'\d+(?:[.,]\d+)?', '{}', b)
T = [
 ('Атака на босса', ["Атака на боса", "Boss Assault", "Bossangriff", "Asalto al jefe", "Ataque ao chefe", "Atak na bossa", "Patron Saldırısı", "Assaut du boss", "Assalto al boss"]),
 ('Босс не умирает — набей как можно больше урона, пока держится стена', ["Бос не вмирає — завдай якомога більше шкоди, поки тримається стіна", "The boss never dies — deal as much damage as you can while the wall holds", "Der Boss stirbt nicht — richte so viel Schaden an wie möglich, solange die Mauer hält", "El jefe no muere: inflige todo el daño que puedas mientras aguante el muro", "O chefe não morre — cause o máximo de dano enquanto a muralha resistir", "Boss nie ginie — zadaj jak najwięcej obrażeń, dopóki trzyma się mur", "Patron ölmez — sur dayandıkça olabildiğince çok hasar ver", "Le boss ne meurt pas : inflige un maximum de dégâts tant que le mur tient", "Il boss non muore: infliggi più danni possibile finché le mura reggono"]),
 ('Босс не умирает: каждая полная полоска здоровья — новая фаза, он бьёт сильнее. Каждые 3 секунды стреляет по стене, раз в минуту шагает на ряд. Со старта — 3 случайных навыка, потом каждую минуту выбор из трёх. Очки — урон по боссу.', ["Бос не вмирає: кожна повна смужка здоров'я — нова фаза, він б'є сильніше. Кожні {} секунди стріляє по стіні, раз на хвилину крокує на ряд. Зі старту — {} випадкові навички, потім щохвилини вибір із трьох. Очки — шкода по босу", "The boss never dies: every full health bar is a new phase and he hits harder. He shoots the wall every {} seconds and steps one row each minute. You start with {} random skills, then pick one of three every minute. Score — damage to the boss", "Der Boss stirbt nicht: jeder volle Lebensbalken ist eine neue Phase, er schlägt härter zu. Alle {} Sekunden schießt er auf die Mauer, einmal pro Minute rückt er eine Reihe vor. Zum Start {} zufällige Fertigkeiten, dann jede Minute eine Wahl aus drei. Punkte — Schaden am Boss", "El jefe no muere: cada barra de vida completa es una nueva fase y golpea más fuerte. Dispara al muro cada {} segundos y avanza una fila cada minuto. Empiezas con {} habilidades al azar y luego eliges una de tres cada minuto. Puntos: daño al jefe", "O chefe não morre: cada barra de vida cheia é uma nova fase e ele bate mais forte. Atira na muralha a cada {} segundos e avança uma fileira por minuto. Você começa com {} habilidades aleatórias e depois escolhe uma de três a cada minuto. Pontos — dano ao chefe", "Boss nie ginie: każdy pełny pasek zdrowia to nowa faza, bije mocniej. Co {} sekundy strzela w mur, raz na minutę schodzi o rząd. Na start {} losowe umiejętności, potem co minutę wybór z trzech. Punkty — obrażenia bossa", "Patron ölmez: her dolu can çubuğu yeni bir evredir, daha sert vurur. Her {} saniyede sura ateş eder, dakikada bir sıra ilerler. Başta {} rastgele yetenek, sonra her dakika üçten birini seçersin. Puan — patrona verilen hasar", "Le boss ne meurt pas : chaque barre de vie pleine est une nouvelle phase, il frappe plus fort. Il tire sur le mur toutes les {} secondes et avance d'une rangée chaque minute. Au départ {} compétences aléatoires, puis un choix parmi trois chaque minute. Score : dégâts infligés au boss", "Il boss non muore: ogni barra di vita piena è una nuova fase e colpisce più forte. Spara alle mura ogni {} secondi e avanza di una fila ogni minuto. All'inizio {} abilità casuali, poi ogni minuto una scelta tra tre. Punti: danni al boss"]),
 ('Босс дня', ["Бос дня", "Boss of the day", "Boss des Tages", "Jefe del día", "Chefe do dia", "Boss dnia", "Günün patronu", "Boss du jour", "Boss del giorno"]),
 ('набей как можно больше урона', ["завдай якомога більше шкоди", "deal as much damage as you can", "richte so viel Schaden an wie möglich", "inflige todo el daño que puedas", "cause o máximo de dano", "zadaj jak najwięcej obrażeń", "olabildiğince çok hasar ver", "inflige un maximum de dégâts", "infliggi più danni possibile"]),
 ('Фаза', ["Фаза", "Phase", "Phase", "Fase", "Fase", "Faza", "Evre", "Phase", "Fase"]),
 ('босс бьёт сильнее', ["бос б'є сильніше", "the boss hits harder", "der Boss schlägt härter zu", "el jefe golpea más fuerte", "o chefe bate mais forte", "boss bije mocniej", "patron daha sert vuruyor", "le boss frappe plus fort", "il boss colpisce più forte"]),
 ('Стена пала — герой держит рубеж!', ["Стіна впала — герой тримає рубіж", "The wall has fallen — the hero holds the line", "Die Mauer ist gefallen — der Held hält die Stellung", "El muro ha caído: el héroe resiste", "A muralha caiu — o herói segura a linha", "Mur padł — bohater trzyma linię", "Sur düştü — kahraman hattı tutuyor", "Le mur est tombé : le héros tient la ligne", "Le mura sono cadute: l'eroe tiene la linea"]),
 ('Новый навык', ["Нова навичка", "New skill", "Neue Fertigkeit", "Nueva habilidad", "Nova habilidade", "Nowa umiejętność", "Yeni yetenek", "Nouvelle compétence", "Nuova abilità"]),
 ('Сначала враги бьют стену, когда она падёт — героя', ["Спершу вороги б'ють стіну, коли вона впаде — героя", "Enemies hit the wall first, once it falls — the hero", "Die Gegner treffen zuerst die Mauer, wenn sie fällt — den Helden", "Los enemigos golpean primero el muro y, cuando cae, al héroe", "Os inimigos atacam primeiro a muralha e, quando ela cai, o herói", "Wrogowie najpierw biją mur, a gdy padnie — bohatera", "Düşmanlar önce suru vurur, sur düşünce kahramanı", "Les ennemis frappent d'abord le mur, puis le héros quand il tombe", "I nemici colpiscono prima le mura, quando cadono l'eroe"]),
 ('Герой пал — поражение', ["Герой загинув — поразка", "The hero falls — defeat", "Der Held fällt — Niederlage", "El héroe cae: derrota", "O herói cai — derrota", "Bohater poległ — porażka", "Kahraman düşerse — yenilgi", "Le héros tombe : défaite", "L'eroe cade: sconfitta"]),
 ('Герой пал', ["Герой загинув", "The hero has fallen", "Der Held ist gefallen", "El héroe ha caído", "O herói caiu", "Bohater poległ", "Kahraman düştü", "Le héros est tombé", "L'eroe è caduto"]),
]

have = set(keys); out = []
for ru, v in T:
    k = key(ru)
    if k in have: continue
    keys.append(k); have.add(k); out.append('|'.join([str(len(keys) - 1)] + v))
json.dump(keys, open(KJ, 'w', encoding='utf8'), ensure_ascii=False, indent=0)
with open('tools/i18n/src/tr20.txt', 'a', encoding='utf8') as o:
    for r in out: o.write(r + '\n')
print('added', len(out))
